def fill_project_slugs(apps, schema_editor):
    from django.utils.text import slugify
    Project = apps.get_model('dashboard', 'Project')
    used = set()
    for project in Project.objects.order_by('pk'):
        base = slugify(project.title)[:50] or 'project'
        slug, n = base, 2
        while slug in used:
            slug = f"{base}-{n}"
            n += 1
        used.add(slug)
        project.slug = slug
        project.save(update_fields=['slug'])


